        color: var(--color-text);
        background-color: var(--color-bg);
        -webkit-font-smoothing: antialiased;
        letter-spacing: -0.01em;
        --section-space: calc(var(--section-y) * var(--section-y-scale));
        overflow-x: clip;
    }

