@layer components {
    .avatar-stack {
        align-items: center;
        display: flex;
    }

    .avatar-stack > img {
        border-radius: var(--radius-full);
        object-fit: cover;
        border: 3px solid var(--color-bg);
        width: 3rem;
        height: 3rem;
        transition: transform var(--duration-base) var(--ease-lift);
        flex-shrink: 0;
        margin-left: -0.85rem;
    }

    .avatar-stack > img:hover {
        z-index: 1;
        position: relative;
        transform: translateY(-3px);
    }

    @media (prefers-reduced-motion: reduce) {
        .avatar-stack > img:hover {
            transform: none;
        }
    }

    .avatar-stack > img:first-child {
        margin-left: 0;
    }

    .avatar-stack-sm > img {
        width: 2.5rem;
        height: 2.5rem;
    }

    .avatar-stack-lg > img {
        width: 3.5rem;
        height: 3.5rem;
    }

    img[src*='/media/avatars/'] {
        background-color: var(--color-bg-muted);
    }

    .btn {
        font-family: var(--font-sans);
        font-size: var(--text-sm);
        font-weight: var(--btn-font-weight);
        line-height: var(--leading-normal);
        letter-spacing: var(--btn-letter-spacing);
        text-transform: var(--btn-text-transform);
        border-radius: var(--btn-radius-override, var(--radius-btn));
        cursor: pointer;
        white-space: nowrap;
        transition:
            background var(--duration-hover) var(--ease-out),
            color var(--duration-hover) var(--ease-out),
            border-color var(--duration-hover) var(--ease-out),
            box-shadow var(--duration-hover) var(--ease-out),
            transform var(--duration-fast) var(--ease-out),
            filter var(--duration-hover) var(--ease-out);
        -webkit-user-select: none;
        user-select: none;
        touch-action: manipulation;
        -webkit-tap-highlight-color: transparent;
        --btn-hover-shadow: 0 10px 22px -10px var(--btn-tint, #0f172a);
        border: 1.5px solid #0000;
        justify-content: center;
        align-items: center;
        gap: 0.5rem;
        padding: 0.85rem 1.625rem;
        text-decoration: none;
        display: inline-flex;

        @supports (color: color-mix(in lab, red, red)) {
            --btn-hover-shadow: 0 10px 22px -10px
                color-mix(in srgb, var(--btn-tint, #0f172a) 75%, transparent);
        }

        --btn-lift-shadow: 0 18px 32px -14px var(--btn-tint, #0f172a);

        @supports (color: color-mix(in lab, red, red)) {
            --btn-lift-shadow: 0 18px 32px -14px
                color-mix(in srgb, var(--btn-tint, #0f172a) 70%, transparent);
        }
    }

    .btn:focus-visible {
        outline: 2px solid var(--btn-tint, var(--color-primary));
        outline-offset: 3px;
    }

    .btn:active {
        transition-duration: 0.12s;
        transform: scale(0.97);
