    .mini-ui {
        --mini-ui-h: 15.5rem;
        --mini-ui-radius: var(--radius-lg);
        --mini-ui-accent: var(--color-primary);
        --mini-ui-on-accent: var(--color-on-primary);
        --mini-ui-ink: oklch(from var(--color-primary) 0.26 calc(c * 0.3) h);
        --mini-ui-art: var(--mini-ui-ink);
        --mini-ui-strong: var(--mini-ui-ink);
        --mini-ui-ground: var(--color-bg-soft);
        --mini-ui-surface: var(--color-surface);
        --mini-ui-line: var(--color-text);

        @supports (color: color-mix(in lab, red, red)) {
            --mini-ui-line: color-mix(in oklch, var(--color-text) 8%, transparent);
        }

        --mini-ui-well: var(--color-text);

        @supports (color: color-mix(in lab, red, red)) {
            --mini-ui-well: color-mix(in oklch, var(--color-text) 6%, var(--mini-ui-surface));
        }

        --mini-ui-muted: var(--color-text);

        @supports (color: color-mix(in lab, red, red)) {
            --mini-ui-muted: color-mix(in oklch, var(--color-text) 28%, transparent);
        }

        --mini-ui-shadow: 0 0.75rem 1.75rem -1rem #00000038, 0 0 0 1px var(--mini-ui-line);
        --mini-ui-btn-radius: var(--btn-radius-override, var(--radius-btn));
        isolation: isolate;
        min-height: var(--mini-ui-h);
        border-radius: var(--mini-ui-radius);
        color: var(--color-text);
        background: var(--mini-ui-ground);
        -webkit-user-select: none;
        user-select: none;
        font-size: 0.8125rem;
        line-height: 1.3;
        position: relative;
        overflow: hidden;
    }

    .mini-ui:not(.ui-card-visual) {
        box-shadow: inset 0 0 0 1px var(--mini-ui-line);
    }

    .mini-ui.mini-ui--ink,
    :is(.dark-section, .section-dark, .bg-dark, .dark-island) .mini-ui:not(.ui-card *) {
        --color-text: white;
        --color-text-soft: #ffffffa3;
        --mini-ui-ground: var(--mini-ui-ink);
        --mini-ui-surface: oklch(from var(--mini-ui-ink) calc(l + 0.07) c h);
        --mini-ui-art: oklch(from var(--mini-ui-ink) calc(l + 0.14) c h);
        --mini-ui-strong: oklch(from var(--mini-ui-ink) calc(l + 0.16) c h);
        --mini-ui-line: #ffffff1a;
        --mini-ui-shadow: 0 0.75rem 1.75rem -1rem #00000080, inset 0 0 0 1px var(--mini-ui-line);
    }

    .mini-ui-surface {
        border-radius: var(--radius-md);
        background: var(--mini-ui-surface);
        box-shadow: var(--mini-ui-shadow);
    }

    .mini-ui-chip {
        border-radius: var(--radius-pill);
        white-space: nowrap;
        color: var(--color-text);
        background: var(--mini-ui-surface);
        align-items: center;
        gap: 0.25rem;
        padding: 0.1875rem 0.5rem;
        font-size: 0.8125rem;
        font-weight: 600;
        line-height: 1.3;
        display: inline-flex;
    }

    .mini-ui-chip--accent {
        color: var(--mini-ui-on-accent);
        background: var(--mini-ui-accent);
    }

    .mini-ui-chip--ink {
        color: #fff;
        background: var(--mini-ui-strong);
        gap: 0.375rem;
        padding: 0.375rem 0.75rem 0.375rem 0.5rem;

        & .ph {
            color: var(--mini-ui-accent);
            font-size: 1rem;
        }
    }

    .mini-ui-pop {
        opacity: 0;
        transition:
            scale 0.6s cubic-bezier(0.34, 1.56, 0.64, 1) var(--pop-delay, 1.5s),
            opacity 0.3s var(--ease-out) var(--pop-delay, 1.5s),
            translate 0.5s var(--ease-out);
        scale: 0.6;
    }

    .mini-ui-line {
        border-radius: var(--radius-pill);
        background: var(--mini-ui-well);
        width: 78%;
        height: 0.5rem;
        display: block;
    }

    .mini-ui-line--short {
        width: 52%;
    }

    .mini-ui-art {
        border-radius: var(--radius-sm);
        background:
            radial-gradient(
                circle at 76% 36%,
                var(--mini-ui-accent) 0 1.125rem,
                transparent calc(1.125rem + 0.5px)
            ),
            linear-gradient(
                160deg,
                oklch(from var(--mini-ui-art) calc(l + 0.06) c h),
                var(--mini-ui-art)
            );
        display: block;
        position: relative;
        overflow: hidden;
    }

    .mini-ui-art--soft {
        background:
            radial-gradient(
                circle at 30% 70%,
                var(--mini-ui-accent) 0 1.75rem,
                transparent calc(1.75rem + 0.5px)
            ),
            var(--mini-ui-well);

        @supports (color: color-mix(in lab, red, red)) {
            background:
                radial-gradient(
                    circle at 30% 70%,
                    color-mix(in oklch, var(--mini-ui-accent) 55%, var(--mini-ui-surface)) 0 1.75rem,
                    transparent calc(1.75rem + 0.5px)
                ),
                var(--mini-ui-well);
        }
    }

    .mini-ui-button {
        border-radius: var(--mini-ui-btn-radius);
        background: var(--mini-ui-accent);
        width: 4.5rem;
        height: 1.375rem;
        display: block;
    }

    .mini-ui-meter {
        border-radius: var(--radius-pill);
        background: var(--mini-ui-well);
        height: 0.375rem;
        display: block;

        & > i {
            width: var(--value, 60%);
            border-radius: inherit;
            background: var(--mini-ui-muted);
            transform-origin: 0;
            height: 100%;
            transition: transform 1.2s var(--ease-out) var(--meter-delay, 0.4s);
            display: block;
            transform: scaleX(0);
        }
    }

    .mini-ui-ring {
        --value: 90;
        aspect-ratio: 1;
        border-radius: var(--radius-full);
        background: var(--mini-ui-surface);
        width: 5.5rem;
        box-shadow: var(--mini-ui-shadow);
        align-content: center;
        place-items: center;
        display: grid;
        position: relative;

        & svg {
            fill: none;
            stroke-width: 5px;
            stroke-linecap: round;
            position: absolute;
            inset: 0.375rem;
            rotate: -90deg;
        }

        & circle:first-child {
            stroke: var(--mini-ui-well);
        }

        & circle:last-child {
            stroke: var(--mini-ui-accent);
            stroke-dasharray: 100;
            stroke-dashoffset: 100px;
            transition: stroke-dashoffset 1.6s var(--ease-out) 0.4s;
        }

        & b {
            font-family: var(--font-tertiary);
            letter-spacing: -0.02em;
            font-variant-numeric: tabular-nums;
            font-size: 1.5rem;
            font-weight: 700;
            line-height: 1;
        }

        & small {
            color: var(--color-text-soft);
            font-size: 0.75rem;
        }
    }

    .mini-ui-live {
        aspect-ratio: 1;
        border-radius: var(--radius-full);
        background: var(--mini-ui-accent);
        width: 0.5rem;
        position: relative;

        &:after {
            content: '';
            border-radius: inherit;
            background: inherit;
            animation: mini-ui-ping 1.8s var(--ease-out) infinite;
            position: absolute;
            inset: 0;
        }
    }

    .mini-ui-float {
        z-index: 1;
        transform-origin: 100% 100%;
        position: absolute;
        bottom: 0.875rem;
        right: 0.875rem;
    }

    :is(.mini-ui-flow-map, .mini-ui-chart-plot) svg {
        fill: none;
        stroke-linecap: round;
        stroke-linejoin: round;
        width: 100%;
        height: 100%;
        position: absolute;
        inset: 0;
        overflow: visible;

        & path {
            vector-effect: non-scaling-stroke;
        }
    }

    .mini-ui:is(.visible, .visible *) {
        & .mini-ui-pop {
            opacity: 1;
            scale: 1;
        }

        & .mini-ui-meter > i {
            transform: none;
        }

        & .mini-ui-ring circle:last-child {
            stroke-dashoffset: calc(100 - var(--value));
        }
    }

    .mini-ui-ads {
        place-items: center;
        display: grid;
        container-type: inline-size;
    }

    .mini-ui-ads-stack {
        width: 9.75rem;
        height: 12.5rem;
        position: relative;
        translate: max(-3.5rem, -11cqi) -0.5rem;
    }

    .mini-ui-ad {
        transition:
            rotate 0.8s var(--ease-out),
            translate 0.8s var(--ease-out);
        flex-direction: column;
        gap: 0.5rem;
        padding: 0.5rem;
        display: flex;
        position: absolute;
        inset: 0;
        rotate: 3deg;

        & > .mini-ui-art {
            border-radius: max(0px, calc(var(--radius-md) - 0.375rem));
            flex: 1;
        }

        & > .mini-ui-line {
            width: 60%;
        }
    }

    .mini-ui-ad:first-child:not(:only-child) {
        translate: -3rem 0.75rem;
        rotate: -8deg;
    }

    .mini-ui-ad-head {
        grid-template-columns: auto minmax(0, 1fr);
        align-items: center;
        column-gap: 0.375rem;
        padding: 0.125rem 0.125rem 0;
        line-height: 1.1;
        display: grid;

        & > i {
            aspect-ratio: 1;
            border-radius: var(--radius-full);
            background: var(--mini-ui-strong)
                radial-gradient(circle, var(--mini-ui-accent) 0 28%, transparent 30%);
            grid-row: span 2;
            width: 1.375rem;
        }

        & b {
            font-weight: 600;
        }

        & small {
            font-size: inherit;
            color: var(--color-text-soft);
        }
    }

    .mini-ui-ad .mini-ui-art > i {
        border-radius: var(--radius-full) var(--radius-full) var(--radius-sm) var(--radius-sm);
        background: #fff;
        height: 2.75rem;
        position: absolute;
        inset: auto 14% -0.75rem;

        @supports (color: color-mix(in lab, red, red)) {
            background: color-mix(in oklch, white 88%, var(--mini-ui-accent));
        }

        transition: translate 0.8s var(--ease-out);
    }

    .mini-ui-ad-cta {
        border-radius: var(--mini-ui-btn-radius);
        color: var(--mini-ui-on-accent);
        background: var(--mini-ui-accent);
        justify-content: space-between;
        align-items: center;
        padding: 0.3125rem 0.375rem 0.3125rem 0.625rem;
        font-weight: 600;
        display: flex;
    }

    .mini-ui .kpi-card {
        --kpi-min-width: 0;
        --kpi-value-size: 1.625rem;
        --kpi-accent: var(--mini-ui-accent);
        border-radius: var(--radius-md);
        background: var(--mini-ui-surface);
        width: 11.25rem;
        box-shadow: var(--mini-ui-shadow);
        padding: 0.875rem 1rem 1rem;

        & .kpi-card-label {
            font-size: 0.8125rem;
        }

        & .kpi-card-bars > i {
            transition:
                transform 0.9s var(--ease-out) calc(0.3s + var(--bar-n, 0) * 70ms),
                height 0.6s var(--ease-out);
            transform: scaleY(0.12);
        }
    }

    .mini-ui:is(.visible, .visible *) .kpi-card .kpi-card-bars > i {
        transform: none;
    }

    .mini-ui-ads > .kpi-card {
        bottom: 1.25rem;
        right: 1.25rem;
    }

    .mini-ui-rank {
        flex-direction: column;
        gap: 0.625rem;
        padding: 1rem;
        display: flex;
    }

    .mini-ui-rank-query {
        border-radius: var(--radius-pill);
        align-items: center;
        gap: 0.5rem;
        padding: 0.5rem 0.875rem;
        font-size: 0.875rem;
        font-weight: 500;
        display: flex;

        & .ph {
            color: var(--color-text-soft);
            font-size: 1rem;
        }
    }

    .mini-ui-rank-list {
        gap: 0.375rem;
        margin: 0;
        padding: 0;
        list-style: none;
        display: grid;

        & > li {
            --n: 0;
            border-radius: var(--radius-pill);
            transition: translate 0.7s var(--ease-out);
            align-items: center;
            gap: 0.625rem;
            padding: 0.375rem 0.75rem 0.375rem 0.375rem;
            display: flex;
        }

        & > li:nth-child(2) {
            --n: 1;
        }

        & > li:nth-child(3) {
            --n: 2;
        }

        & > li:nth-child(4) {
            --n: 3;
        }
    }

    .mini-ui-rank-pos {
        border-radius: var(--radius-pill);
        width: 2rem;
        height: 1.625rem;
        font-family: var(--font-tertiary);
        font-variant-numeric: tabular-nums;
        text-align: center;
        background: var(--mini-ui-well);
        transition:
            background-color 0.5s var(--ease-out) 1s,
            color 0.5s var(--ease-out) 1s;
        flex: none;
        font-size: 0.875rem;
        overflow: hidden;

        & > span {
            transition: translate 0.9s cubic-bezier(0.7, 0, 0.2, 1) calc(var(--n) * 0.12s + 0.35s);
            display: grid;
        }

        & b {
            font-weight: 700;
            line-height: 1.625rem;
        }

        & b:before {
            content: '#';
            opacity: 0.55;
            font-weight: 600;
        }
    }

    .mini-ui-rank-label {
        white-space: nowrap;
        text-overflow: ellipsis;
        flex: 1;
        min-width: 0;
        font-weight: 500;
        overflow: hidden;
    }

    .mini-ui-rank-move {
        color: var(--color-text-soft);
        opacity: 0;
        transition: opacity 0.4s var(--ease-out) calc(var(--n) * 0.12s + 1.1s);
        align-items: center;
        gap: 0.125rem;
        font-weight: 600;
        display: inline-flex;
    }

    .mini-ui:is(.visible, .visible *) {
        & .mini-ui-rank-pos > span {
            translate: 0 -50%;
        }

        & .mini-ui-rank-move {
            opacity: 1;
        }

        & .is-active .mini-ui-rank-pos {
            color: var(--mini-ui-on-accent);
            background-color: var(--mini-ui-accent);
        }
    }

    .mini-ui-browser-window {
        transition: translate 0.7s var(--ease-out);
        flex-direction: column;
        display: flex;
        position: absolute;
        inset: 1rem 2.75rem -1.5rem 1rem;
        overflow: hidden;
    }

    .mini-ui-browser-bar {
        border-bottom: 1px solid var(--mini-ui-line);
        align-items: center;
        gap: 0.3125rem;
        padding: 0.5rem 0.75rem;
        display: flex;

        & > i {
            aspect-ratio: 1;
            border-radius: var(--radius-full);
            background: var(--mini-ui-muted);
            width: 0.4375rem;
        }

        & > span {
            border-radius: var(--radius-pill);
            color: var(--color-text-soft);
            background: var(--mini-ui-well);
            margin-inline: auto;
            padding: 0.125rem 0.875rem;
        }
    }

    .mini-ui-browser-page {
        flex-direction: column;
        gap: 0.5rem;
        padding: 0.75rem;
        display: flex;

        & > .mini-ui-art {
            flex: none;
            height: 4.5rem;
        }

        & > .mini-ui-button {
            margin-top: 0.25rem;
        }
    }

    .mini-ui-ab {
        grid-template-columns: repeat(2, minmax(0, 1fr));
        gap: 0.75rem;
        padding: 1rem;
        display: grid;
    }

    .mini-ui-ab-variant {
        transition:
            opacity 0.5s var(--ease-out),
            box-shadow 0.5s var(--ease-out);
        flex-direction: column;
        gap: 0.5rem;
        padding: 0.625rem;
        display: flex;
        position: relative;

        & > .mini-ui-chip {
            transform-origin: 100% 0;
            position: absolute;
            top: 0.5rem;
            right: 0.5rem;
        }
    }

    .mini-ui-ab-tag {
        aspect-ratio: 1;
        border-radius: var(--radius-full);
        background: var(--mini-ui-well);
        place-items: center;
        width: 1.5rem;
        font-weight: 700;
        display: grid;
    }

    .mini-ui-ab-preview {
        flex-direction: column;
        flex: 1;
        gap: 0.3125rem;
        display: flex;

        & > i {
            border-radius: var(--radius-xs);
            background: var(--mini-ui-well);
            display: block;
        }

        & > i:first-child {
            flex: 1;
            min-height: 2rem;
        }

        & > i:nth-child(2) {
            width: 70%;
            height: 0.375rem;
        }

        & > i:nth-child(3) {
            border-radius: var(--mini-ui-btn-radius);
            background: var(--mini-ui-muted);
            width: 46%;
            height: 0.875rem;
        }
    }

    .mini-ui-ab-rate {
        font-family: var(--font-tertiary);
        letter-spacing: -0.02em;
        font-variant-numeric: tabular-nums;
        font-size: 1.375rem;
        font-weight: 700;
        line-height: 1;
    }

    .mini-ui-ab-variant.is-winner {
        --meter-delay: 0.6s;

        & .mini-ui-ab-preview > i:first-child {
            background: linear-gradient(
                160deg,
                oklch(from var(--mini-ui-art) calc(l + 0.06) c h),
                var(--mini-ui-art)
            );
        }

        & .mini-ui-ab-preview > i:nth-child(3) {
            background: var(--mini-ui-accent);
            width: 64%;
        }

        & .mini-ui-meter > i {
            background: var(--mini-ui-accent);
        }
    }

    .mini-ui-flow {
        --mini-ui-h: 18rem;
        flex-direction: column;
        padding: 1rem 1.25rem 1.25rem;
        display: flex;
    }

    .mini-ui-flow-head {
        justify-content: space-between;
        align-items: center;
        gap: 1rem;
        font-size: 0.875rem;
        display: flex;

        & b {
            font-weight: 600;
        }

        & > .mini-ui-chip {
            gap: 0.5rem;
            font-weight: 500;
        }
    }

    .mini-ui-flow-map {
        flex: 1;
        min-height: 9rem;
        margin-block: 0.5rem 1rem;
        display: block;
        position: relative;

        & path:first-child {
            stroke: var(--mini-ui-muted);
            stroke-width: 1.5px;
            stroke-dasharray: 0.006 0.014;
            stroke-dashoffset: 0;
            transition: none;
        }

        & path:last-child {
            --draw-duration: 2.4s;
            --draw-delay: 0.3s;
            stroke: var(--color-text);
            stroke-width: 2.5px;
        }
    }

    .mini-ui-flow-step {
        --i: 0;
        top: calc(19.44% - 1.25rem);
        left: calc(12.5% + 25% * var(--i));
        text-align: center;
        justify-items: center;
        width: 25%;
        line-height: 1.15;
        display: grid;
        position: absolute;
        translate: -50%;

        & > .ph {
            aspect-ratio: 1;
            border-radius: var(--radius-full);
            background: var(--mini-ui-surface);
            width: 2.5rem;
            box-shadow: var(--mini-ui-shadow);
            transition:
                background-color 0.5s var(--ease-out),
                color 0.5s var(--ease-out),
                scale 0.5s var(--ease-out);
            transition-delay: calc(var(--i) * 0.35s + 0.4s);
            place-items: center;
            margin-bottom: 0.375rem;
            font-size: 1.125rem;
            display: grid;
        }

        & :is(b, small) {
            border-radius: var(--radius-xs);
            font-size: inherit;
            white-space: nowrap;
            background: var(--mini-ui-ground);
            padding-inline: 0.25rem;
        }

        & b {
            font-weight: 600;
        }

        & small {
            color: var(--color-text-soft);
        }
    }

    .mini-ui-flow-step:nth-of-type(2) {
        --i: 1;
        top: calc(58.33% - 1.25rem);
    }

    .mini-ui-flow-step:nth-of-type(3) {
        --i: 2;
    }

    .mini-ui-flow-step:nth-of-type(4) {
        --i: 3;
        top: calc(58.33% - 1.25rem);
    }

    .mini-ui-flow-foot {
        border-radius: var(--radius-pill);
        white-space: nowrap;
        color: var(--color-text-soft);
        justify-content: space-between;
        align-items: center;
        gap: 1rem;
        padding: 0.5rem 0.5rem 0.5rem 1rem;
        font-size: 0.875rem;
        display: flex;

        & > span {
            align-items: center;
            gap: 0.5rem;
            display: inline-flex;
        }

        & b {
            font-family: var(--font-tertiary);
            color: var(--color-text);
            font-size: 1.125rem;
            font-weight: 700;
        }
    }

    .mini-ui:is(.visible, .visible *) .mini-ui-flow-step > .ph {
        color: var(--mini-ui-on-accent);
        background: var(--mini-ui-accent);
    }

    .mini-ui-chart {
        --mini-ui-h: 18rem;
        color: var(--color-text-soft);
        flex-direction: column;
        gap: 0.75rem;
        padding: 1rem 1.125rem 0.875rem;
        display: flex;
    }

    .mini-ui-chart-legend {
        gap: 1rem;
        display: flex;

        & > span {
            align-items: center;
            gap: 0.375rem;
            display: inline-flex;
        }

        & i {
            border-radius: var(--radius-pill);
            background: var(--mini-ui-accent);
            width: 0.875rem;
            height: 0.1875rem;
        }

        & > span + span i {
            background: var(--mini-ui-muted);
        }
    }

    .mini-ui-chart-plot {
        --x: 75%;
        --y: 30%;
        flex: 1;
        margin-inline: 0.25rem;
        display: block;
        position: relative;

        & path {
            stroke: var(--mini-ui-accent);
            stroke-width: 2.5px;
        }

        & path:not(:last-child) {
            --draw-delay: 0.5s;
            stroke: var(--mini-ui-muted);
            stroke-width: 2px;
        }

        & path {
            --draw-duration: 2.6s;
        }
    }

    .mini-ui-chart-area {
        opacity: 0;
        transition: opacity 1s var(--ease-out) 1.4s;
        mask-image: linear-gradient(#000, #0000);

        & path {
            fill: var(--mini-ui-accent);
            stroke: none;
        }
    }

    .mini-ui-chart-point {
        inset-block: 0;
        left: var(--x);
        border-left: 1px dashed var(--mini-ui-muted);
        position: absolute;

        &:after {
