    .word-rotator {
        --wr-dur: 0.55s;
        --wr-ease: cubic-bezier(0.22, 0.61, 0.36, 1);
        vertical-align: bottom;
        transition: width var(--wr-dur) var(--wr-ease);
        --wr-bleed: 0.18em;
        box-sizing: content-box;
        padding-bottom: 0.14em;
        padding-inline: var(--wr-bleed);
        margin-bottom: -0.14em;
        margin-inline: calc(var(--wr-bleed) * -1);
        display: inline-block;
        position: relative;
        overflow: hidden;
    }

    .word-rotator-word {
        left: var(--wr-bleed);
        white-space: nowrap;
        transition:
            transform var(--wr-dur) var(--wr-ease),
            opacity var(--wr-dur) var(--wr-ease),
            filter var(--wr-dur) var(--wr-ease);
        position: absolute;
        top: 0;
    }

    .word-rotator-word.is-active {
        position: relative;
        left: 0;
    }

    .word-rotator-word {
        opacity: 0;
        transform: translateY(calc(100% + 0.14em));
    }

    .word-rotator-word.is-active {
        opacity: 1;
        transform: translateY(0);
    }

    .word-rotator-word.is-leaving {
        opacity: 0;
        transform: translateY(-100%);
    }

    .word-rotator--slide-down .word-rotator-word {
        transform: translateY(-100%);
    }

    .word-rotator--slide-down .word-rotator-word.is-active {
        transform: translateY(0);
    }

    .word-rotator--slide-down .word-rotator-word.is-leaving {
        transform: translateY(calc(100% + 0.14em));
    }

    .word-rotator--fade .word-rotator-word,
    .word-rotator--fade .word-rotator-word.is-active,
    .word-rotator--fade .word-rotator-word.is-leaving {
        transform: none;
    }

    .word-rotator--fade .word-rotator-word {
        opacity: 0;
    }

    .word-rotator--fade .word-rotator-word.is-active {
        opacity: 1;
    }

    .word-rotator--flip {
        perspective: 320px;
        overflow: visible;
    }

    .word-rotator--flip .word-rotator-word {
        transform-origin: 50% 100%;
        backface-visibility: hidden;
        opacity: 0;
        transform: rotateX(-90deg);
    }

    .word-rotator--flip .word-rotator-word.is-active {
        opacity: 1;
        transform: rotateX(0);
    }

    .word-rotator--flip .word-rotator-word.is-leaving {
        opacity: 0;
        transform: rotateX(90deg);
    }

    .word-rotator--blur .word-rotator-word {
        opacity: 0;
        filter: blur(8px);
        transform: scale(1.04);
    }

    .word-rotator--blur .word-rotator-word.is-active {
        opacity: 1;
        filter: blur();
        transform: none;
    }

    .word-rotator--blur .word-rotator-word.is-leaving {
        opacity: 0;
        filter: blur(8px);
        transform: scale(0.96);
    }

    .word-rotator--type {
        overflow: visible;
    }

    .word-rotator--type .word-rotator-word {
        opacity: 1;
        filter: none;
        will-change: auto;
        transition: none;
        position: relative;
        transform: none;
    }

    .word-rotator--type .word-rotator-word:not(.is-active) {
        display: none;
    }

    .word-rotator--type .word-rotator-word.is-active:after {
        content: '';
        vertical-align: -0.15em;
        background: currentColor;
        width: 0.08em;
        height: 1.05em;
        margin-left: 0.06em;
        animation: 1s step-end infinite wr-caret;
        display: inline-block;
    }

    @keyframes wr-caret {
        50% {
            opacity: 0;
        }
    }

    .word-rotator[class*='text-gradient-'] .word-rotator-word {
        background: inherit;
        -webkit-text-fill-color: transparent;
        color: #0000;
        background-clip: text;
    }

    @media (prefers-reduced-motion: reduce) {
        .word-rotator,
        .word-rotator-word {
            transition: none !important;
        }

        .word-rotator-word {
            filter: none !important;
            transform: none !important;
        }

        .word-rotator-word:not(.is-active) {
            opacity: 0;
        }

        .word-rotator-word.is-active {
            opacity: 1;
        }

        .word-rotator--type .word-rotator-word.is-active:after {
            animation: none;
        }
    }

