                align-items: center;
                width: 100%;
            }

            & .timeline-item-line {
                width: auto;
                height: var(--route-line-width);
                flex: 1;
                margin: 0;
            }

            & .timeline-item:last-child .timeline-item-line {
                background: linear-gradient(to right, var(--route-line), transparent);
            }

            & .timeline-item-content,
            & .timeline-item:last-child .timeline-item-content {
                padding: 1.5rem 2rem 0 0;
            }
        }

        .timeline--route.timeline--numbered {
            & .timeline-item {
                gap: 0;
            }

            & .timeline-item-date {
                margin-top: 0;
            }
        }

        .timeline--route.timeline--terminus .timeline-item:last-child .timeline-item-line {
            background: linear-gradient(var(--route-line), var(--route-line)) left /
                calc(100% - var(--route-end)) 100% no-repeat;

            &:after {
                inset: 50% 0 auto auto;
                translate: 0 -50%;
            }
        }

        .timeline--route.timeline--signal:after {
            top: calc(var(--route-dot) / 2);
            right: var(--route-end);
            width: auto;
            height: var(--route-line-width);
            background: linear-gradient(to right, transparent, var(--route-signal)) -4rem 0 / 4rem
                100% no-repeat;
            bottom: auto;
            translate: 0 -50%;
        }
    }

    @media (prefers-reduced-motion: no-preference) and (scripting: enabled) {
        .timeline--route[data-anim]:not(.visible) {
            & .timeline-item-dot {
                opacity: 0;
                scale: 0.4;
            }

            & .timeline-item-line {
                scale: var(--route-from);
            }

            & .timeline-item-content {
                opacity: 0;
            }

            & .timeline-item:last-child .timeline-item-line:after {
                opacity: 0;
                scale: 0.4;
            }
        }

        .timeline--route.visible {
            & .timeline-item-dot {
                animation: timeline-route-pop 0.6s var(--ease-lift)
                    calc(var(--route-i) * var(--route-step)) both;
            }

            & .timeline-item-line {
                animation: timeline-route-draw var(--route-step) linear
                    calc(var(--route-i) * var(--route-step)) both;
            }

            & .timeline-item-content {
                animation: timeline-route-rise 0.7s var(--ease-out)
                    calc(var(--route-i) * var(--route-step) + 80ms) both;
            }

            & .timeline-item:last-child .timeline-item-line:after {
                animation: timeline-route-pop 0.6s var(--ease-lift)
                    calc((var(--route-i) + 1) * var(--route-step)) both;
            }
        }

        .timeline--route.timeline--signal:after {
            animation: 6s cubic-bezier(0.45, 0, 0.4, 1) 1s infinite timeline-route-run-y;
        }

        .timeline--route.timeline--signal[data-anim]:after {
            animation-delay: 2.4s;
        }

        .timeline--route.timeline--signal[data-anim]:not(.visible):after {
            animation: none;
        }

        @media (width >= 1024px) {
            .timeline--route.timeline--signal:after {
                animation-name: timeline-route-run-x;
            }
        }
    }

    @keyframes timeline-route-draw {
