    }

    .counter-grid--filled {
        --counter-color: var(--color-primary);
        --counter-color-on: var(--color-on-primary);
        background: #fff;

        @supports (color: color-mix(in lab, red, red)) {
            background: color-mix(in srgb, #fff 22%, var(--counter-color));
        }

        box-shadow: 0 24px 48px -20px var(--counter-color);
        border-color: #0000;

        @supports (color: color-mix(in lab, red, red)) {
            box-shadow: 0 24px 48px -20px color-mix(in srgb, var(--counter-color) 60%, transparent);
        }
    }

    .counter-grid--filled > .counter {
        background: var(--counter-color);
    }

    .counter-grid--filled > .counter:hover {
        background: #fff;

        @supports (color: color-mix(in lab, red, red)) {
            background: color-mix(in srgb, #fff 10%, var(--counter-color));
        }
    }

    .counter-grid--filled .counter-number {
        color: var(--counter-color-on, #fff);
    }

    .counter-grid--filled .counter-label {
        color: oklch(from var(--counter-color-on, #fff) l c h / 0.85);
    }

    .counter--circle {
        color: var(--color-primary-ink);
    }

    .counter-circle {
        width: 9rem;
        height: 9rem;
        margin-bottom: 0.75rem;
        position: relative;
    }

    .counter-circle-svg {
        width: 100%;
        height: 100%;
        display: block;
        overflow: visible;
        transform: rotate(-90deg);
    }

    .counter-circle-track,
    .counter-circle-bar {
        fill: none;
        stroke-width: 6px;
    }

    .counter-circle-track {
        stroke: currentColor;
        opacity: 0.16;
    }

    .counter-circle-bar {
        stroke: currentColor;
        stroke-linecap: round;
        stroke-dasharray: 339.292;
        stroke-dashoffset: 339.292px;
        filter: drop-shadow(0 0 6px);

        @supports (color: color-mix(in lab, red, red)) {
            filter: drop-shadow(0 0 6px color-mix(in srgb, currentColor 35%, transparent));
        }
    }

    .counter-circle .counter-number {
        font-size: var(--text-3xl);
        letter-spacing: -0.04em;
        justify-content: center;
        align-items: center;
        display: flex;
        position: absolute;
        inset: 0;
    }

    .counter--circle.counter--sm .counter-circle {
        width: 6rem;
        height: 6rem;
    }

    .counter--circle.counter--sm .counter-number {
        font-size: var(--text-xl);
    }

    .counter--circle.counter--lg .counter-circle {
        width: 12rem;
        height: 12rem;
    }

    .counter--circle.counter--lg .counter-number {
        font-size: var(--text-4xl);
    }

    .counter-number--odometer {
        align-items: center;
        display: inline-flex;
        position: relative;
    }

    .counter-odometer-value {
        clip-path: inset(50%);
        white-space: nowrap;
        width: 1px;
        height: 1px;
        position: absolute;
        overflow: hidden;
    }

    .counter-odometer-digit {
        height: 1em;
        display: block;
        overflow: hidden;
    }

    .counter-odometer-reel {
        will-change: transform;
        flex-direction: column;
        display: flex;
        transform: translateY(0);
    }

    .counter-odometer-reel > span,
    .counter-odometer-static {
        justify-content: center;
        align-items: center;
        height: 1em;
        display: flex;
    }

    .counter-inline {
        font-size: inherit;
        font-variant-numeric: tabular-nums;
        letter-spacing: -0.01em;
        font-weight: 700;
        font-family: var(--font-heading);
        color: var(--color-primary-ink);
        display: inline;
    }

    .stat-bars {
        --stat-bars-base: 13.5rem;
        --stat-bars-step: 1.5rem;
        grid-template-columns: repeat(2, minmax(0, 1fr));
        align-items: end;
        gap: 0.75rem;
        margin: 0;
        padding: 0;
        list-style: none;
        display: grid;
    }

    .stat-bar {
        --stat-bar-soft: var(--color-text-soft);
        isolation: isolate;
        min-height: calc(var(--stat-bars-base) + var(--stat-bar-n, 0) * var(--stat-bars-step));
        border-radius: var(--radius-20);
        color: var(--color-text);
        background: var(--stat-bar-bg, var(--color-bg-soft));
        flex-direction: column;
        padding: 1.125rem 1.125rem 1.25rem;
        display: flex;
        position: relative;
        overflow: clip;
        container-type: inline-size;

        &:nth-child(2) {
            --stat-bar-n: 1;
        }

        &:nth-child(3) {
            --stat-bar-n: 2;
        }

        &:nth-child(4) {
            --stat-bar-n: 3;
        }

        &:nth-child(5) {
            --stat-bar-n: 4;
        }

        &:nth-child(6) {
            --stat-bar-n: 5;
        }

        &:last-child:nth-child(odd) {
            grid-column: 1 / -1;
        }
    }

    .stat-bar-top {
        justify-content: space-between;
        align-items: start;
        gap: 0.75rem;
        margin-bottom: auto;
        padding-bottom: 1.25rem;
        display: flex;
    }

    .stat-bar-index {
        letter-spacing: 0.04em;
        font-variant-numeric: tabular-nums;
        color: var(--stat-bar-soft);
        font-size: 0.875rem;
        font-weight: 600;
    }

    .stat-bar-figure {
        font-family: var(--stat-bar-font, var(--font-heading));
        font-size: var(--stat-bar-figure-size, clamp(2.25rem, 27cqi, 6rem));
        letter-spacing: -0.045em;
        font-variant-numeric: tabular-nums;
        white-space: nowrap;
        margin: 0;
        font-weight: 700;
        line-height: 0.92;

        & small {
            letter-spacing: -0.02em;
            margin-left: 0.04em;
            font-size: 0.46em;
            font-weight: 600;
        }
    }

    .stat-bar-label {
        font-size: var(--text-base);
        letter-spacing: -0.005em;
        margin: 0.875rem 0 0;
        font-weight: 600;
        line-height: 1.3;
    }

    .stat-bar-caption {
        font-size: var(--text-base);
        color: var(--stat-bar-soft);
        text-wrap: pretty;
        margin: 0.25rem 0 0;
        line-height: 1.45;
    }

    .stat-bar-viz {
        flex: none;
    }

    .stat-bar--primary {
        --stat-bar-soft: var(--color-on-primary);

        @supports (color: color-mix(in lab, red, red)) {
            --stat-bar-soft: color-mix(in oklch, var(--color-on-primary) 74%, transparent);
        }

        --stat-bar-accent: var(--color-on-primary);
        --stat-bar-dot: var(--color-primary);
        color: var(--color-on-primary);
        background: var(--color-primary);

        &:before {
            content: '';
            z-index: -1;
            pointer-events: none;
            background-image: radial-gradient(var(--color-on-primary) 1.25px, transparent 1.75px);
            width: 75%;
            height: 60%;
            position: absolute;
            inset: 0 0 auto auto;

            @supports (color: color-mix(in lab, red, red)) {
                background-image: radial-gradient(
                    color-mix(in oklch, var(--color-on-primary) 24%, transparent) 1.25px,
                    transparent 1.75px
                );
            }

            background-size: 14px 14px;
            mask: linear-gradient(to bottom left, #000, #0000 72%);
        }
    }

    .stat-bar--dark {
        --stat-bar-soft: var(--color-on-dark);

        @supports (color: color-mix(in lab, red, red)) {
            --stat-bar-soft: color-mix(in oklch, var(--color-on-dark) 64%, transparent);
        }

        color: var(--color-on-dark);
        background: var(--color-dark);
    }

    .stat-bars--raised .stat-bar:not(.stat-bar--primary, .stat-bar--dark) {
        background: var(--stat-bar-bg, var(--color-surface));
        box-shadow:
