            0 1px 2px var(--color-dark);

        @supports (color: color-mix(in lab, red, red)) {
            box-shadow:
                inset 0 0 0 1px var(--color-border-soft),
                0 1px 2px color-mix(in oklch, var(--color-dark) 4%, transparent);
        }
    }

    :is(.dark-section, .section-dark, .bg-dark) .stat-bar:not(.stat-bar--primary) {
        --stat-bar-soft: oklch(from var(--on-surface, white) l c h / 0.62);
        color: var(--on-surface, white);
        background: var(--stat-bar-bg, oklch(from var(--on-surface, white) l c h / 0.06));
        box-shadow: inset 0 0 0 1px oklch(from var(--on-surface, white) l c h / 0.08);
    }

    @media (width >= 640px) {
        .stat-bar {
            padding: 1.5rem 1.5rem 1.625rem;
        }
    }

    @media (width >= 1024px) {
        .stat-bars {
            --stat-bars-base: 17rem;
            --stat-bars-step: 3.25rem;
            grid-template-columns: none;
            grid-auto-columns: minmax(0, 1fr);
