        @supports (color: color-mix(in lab, red, red)) {
            box-shadow:
                0 1.25rem 3rem -1rem color-mix(in oklch, var(--color-dark) 28%, transparent),
                0 0 0 1px color-mix(in oklch, var(--color-dark) 6%, transparent);
        }
