        font-size: 0.8125rem;
        font-weight: 600;
        line-height: 1.4;
        display: inline-flex;
    }

    .kpi-card-delta--up {
        color: var(--color-success);
        background: var(--color-success);

        @supports (color: color-mix(in lab, red, red)) {
            background: color-mix(in oklch, var(--color-success) 12%, transparent);
        }
    }

    .kpi-card-delta--down {
        color: var(--color-danger);
        background: var(--color-danger);

        @supports (color: color-mix(in lab, red, red)) {
            background: color-mix(in oklch, var(--color-danger) 11%, transparent);
        }
    }

    .kpi-card-spark {
        width: 100%;
        height: var(--kpi-chart-height, 2.75rem);
        fill: none;
        stroke: var(--kpi-accent, var(--color-primary-ink));
        stroke-width: 2.5px;
        stroke-linecap: round;
        stroke-linejoin: round;
        margin-top: 0.5rem;
        display: block;
        overflow: visible;
    }

    .kpi-card--glass {
        --kpi-accent: oklch(from var(--color-primary) max(l, 0.72) c h);
        color: #fff;
        background: var(--kpi-glass-bg, var(--color-dark));

        @supports (color: color-mix(in lab, red, red)) {
            background: var(
                --kpi-glass-bg,
                color-mix(in oklch, var(--color-dark) 42%, transparent)
            );
        }

        -webkit-backdrop-filter: blur(18px) saturate(140%);
        backdrop-filter: blur(18px) saturate(140%);
        box-shadow:
            0 1.25rem 3rem -1rem #0006,
            inset 0 0 0 1px #ffffff24;

        & .kpi-card-label {
            color: #ffffffb8;
        }
    }

    .kpi-card--flat {
        min-width: 0;
        box-shadow: inset 0 0 0 1px var(--color-border);
        gap: 0.375rem;
        padding: 1.375rem 1.5rem 1.5rem;

        & .kpi-card-label {
            font-size: var(--text-base);
        }

        & .kpi-card-value {
            font-size: var(--kpi-value-size, 2.25rem);
        }
    }

    :is(.dark-section, .section-dark, .bg-dark) .kpi-card--flat {
        --kpi-accent: oklch(from var(--color-primary) max(l, 0.72) c h);
        color: var(--on-surface, white);
        background: oklch(from var(--on-surface, white) l c h / 0.06);
        box-shadow: inset 0 0 0 1px oklch(from var(--on-surface, white) l c h / 0.1);

        & .kpi-card-label {
            color: oklch(from var(--on-surface, white) l c h / 0.66);
        }
    }

    :is(.kpi-card--glass, :is(.dark-section, .section-dark, .bg-dark) .kpi-card--flat) {
        & .kpi-card-delta--up {
            color: oklch(from var(--color-success) max(l, 0.8) c h);
            background: var(--color-success);

            @supports (color: color-mix(in lab, red, red)) {
                background: color-mix(in oklch, var(--color-success) 24%, transparent);
            }
        }

        & .kpi-card-delta--down {
            color: oklch(from var(--color-danger) max(l, 0.78) c h);
            background: var(--color-danger);

            @supports (color: color-mix(in lab, red, red)) {
                background: color-mix(in oklch, var(--color-danger) 24%, transparent);
            }
        }
    }

    :is(.stat-bar-bars, .kpi-card-bars) {
