        & > i {
            height: var(--bar);
            border-radius: var(--radius-xs);
            transform-origin: bottom;
            transition: transform 0.9s var(--ease-out) calc(0.25s + var(--bar-n, 0) * 70ms);
            flex: 1;
        }

        & > i:first-child {
            --bar: 30%;
        }

        & > i:nth-child(2) {
            --bar: 42%;
            --bar-n: 1;
        }

        & > i:nth-child(3) {
            --bar: 38%;
            --bar-n: 2;
        }

        & > i:nth-child(4) {
            --bar: 56%;
            --bar-n: 3;
        }

        & > i:nth-child(5) {
            --bar: 64%;
            --bar-n: 4;
        }

        & > i:nth-child(6) {
            --bar: 80%;
            --bar-n: 5;
        }

        & > i:nth-child(7) {
            --bar: 100%;
            --bar-n: 6;
        }
    }

    :is(.stat-bar, .kpi-card)[data-anim]:not(.visible) :is(.stat-bar-bars, .kpi-card-bars) > i {
        transform: scaleY(0);
    }

    .stat-bar-bars {
        gap: 0.1875rem;
        width: 4.75rem;
        height: 2rem;

        & > i {
            background: currentColor;

            @supports (color: color-mix(in lab, red, red)) {
                background: color-mix(in oklch, currentColor 16%, transparent);
            }
        }

        & > i:last-child {
            background: var(--stat-bar-accent, var(--color-primary));
        }
    }

    .kpi-card-bars {
        height: var(--kpi-chart-height, 2.75rem);
        gap: 0.3125rem;
        margin-top: 0.5rem;

        & > i {
            background: var(--kpi-accent, var(--color-primary));

            @supports (color: color-mix(in lab, red, red)) {
                background: color-mix(
                    in oklch,
                    var(--kpi-accent, var(--color-primary)) 30%,
                    transparent
                );
            }
        }

        & > i:last-child {
            background: var(--kpi-accent, var(--color-primary));
        }
    }

    .kpi-card--glass .kpi-card-bars > i:not(:last-child) {
        background: var(--kpi-glass-bars, #fff3);
    }

    .stat-bar-spark {
        fill: none;
        stroke: currentColor;
        stroke-width: 2px;
        stroke-linecap: round;
        stroke-linejoin: round;
        width: 6rem;
        height: 2rem;
        overflow: visible;

        & circle {
            fill: var(--stat-bar-dot, var(--stat-bar-accent, var(--color-primary-ink)));
            transition: opacity var(--duration-fast) var(--ease-out)
                calc(var(--draw-delay, 0.2s) + var(--draw-duration, 1.8s) * 0.55);
        }

        &[data-anim]:not(.visible) circle {
            opacity: 0;
        }
