    .svg-draw.stat-bar-spark circle {
        stroke-dasharray: none;
    }

    .stat-bar-ring {
        fill: none;
        stroke-width: 4.5px;
        width: 2.25rem;
        height: 2.25rem;
        rotate: -90deg;
    }

    .stat-bar-ring-track {
        stroke: currentColor;

        @supports (color: color-mix(in lab, red, red)) {
            stroke: color-mix(in oklch, currentColor 14%, transparent);
        }
    }

    .stat-bar-ring-bar {
        stroke: currentColor;
        stroke-linecap: round;
        stroke-dasharray: 1;
        stroke-dashoffset: calc(1 - var(--ring, 0.75));
        transition: stroke-dashoffset 1.6s var(--ease-out) 0.5s;
    }

    .stat-bar-ring[data-anim]:not(.visible) .stat-bar-ring-bar {
        stroke-dashoffset: 1px;
