        :is(.stat-bar, .kpi-card)[data-anim]:not(.visible) :is(.stat-bar-bars, .kpi-card-bars) > i {
            transform: none;
        }

        .stat-bar-spark[data-anim]:not(.visible) circle {
            opacity: 1;
        }

        .stat-bar-ring[data-anim]:not(.visible) .stat-bar-ring-bar {
            stroke-dashoffset: calc(1 - var(--ring, 0.75));
