        letter-spacing: -0.01em;
        flex-shrink: 0;
        font-weight: 600;
    }

    .progress--primary {
        --progress-color: var(--color-primary);
        --progress-color-on: var(--color-on-primary);
    }

    .progress--secondary {
        --progress-color: var(--color-secondary);
        --progress-color-on: var(--color-on-secondary);
    }

    .progress--tertiary {
        --progress-color: var(--color-tertiary);
        --progress-color-on: var(--color-on-tertiary);
    }

    .progress--quaternary {
        --progress-color: var(--color-quaternary);
        --progress-color-on: var(--color-on-quaternary);
    }

    .progress--accent {
        --progress-color: var(--color-accent);
        --progress-color-on: var(--color-on-accent);
    }

    .progress--dark {
        --progress-color: var(--color-dark);
        --progress-color-on: var(--color-on-dark);
    }

    .progress-bar--primary {
        --progress-color: var(--color-primary);
        --progress-color-on: var(--color-on-primary);
    }

    .progress-bar--secondary {
        --progress-color: var(--color-secondary);
        --progress-color-on: var(--color-on-secondary);
    }

    .progress-bar--tertiary {
        --progress-color: var(--color-tertiary);
        --progress-color-on: var(--color-on-tertiary);
    }

    .progress-bar--quaternary {
        --progress-color: var(--color-quaternary);
        --progress-color-on: var(--color-on-quaternary);
    }

    .progress-bar--accent {
        --progress-color: var(--color-accent);
        --progress-color-on: var(--color-on-accent);
    }

    .progress-bar--dark {
        --progress-color: var(--color-dark);
        --progress-color-on: var(--color-on-dark);
    }

    .progress--xs {
        height: 0.25rem;
    }

    .progress--sm {
        height: 0.5rem;
    }

    .progress--lg {
        height: 1rem;
    }

    .progress--square {
        border-radius: 0;
    }

    .progress--rounded {
        border-radius: var(--radius-sm);
    }

    .progress--striped .progress-bar {
        background-color: var(--progress-color, var(--color-primary));
        background-image: linear-gradient(
            45deg,
            #ffffff2e 25%,
            #0000 25% 50%,
            #ffffff2e 50% 75%,
            #0000 75%,
            #0000
        );
        background-size: 1rem 1rem;
    }

    .progress--animated .progress-bar {
        animation: 1s linear infinite progress-stripes;
    }

    .progress--gradient .progress-bar {
        background-image: linear-gradient(
            90deg,
            var(--progress-color, var(--color-primary)),
            var(--progress-color, var(--color-primary))
        );

        @supports (color: color-mix(in lab, red, red)) {
            background-image: linear-gradient(
                90deg,
                var(--progress-color, var(--color-primary)),
                color-mix(in srgb, var(--progress-color, var(--color-primary)) 45%, #fff)
            );
        }
    }

    .progress--glow {
        overflow: visible;
    }

    .progress--glow .progress-bar {
        box-shadow: 0 2px 14px var(--progress-color, var(--color-primary));

        @supports (color: color-mix(in lab, red, red)) {
            box-shadow: 0 2px 14px
                color-mix(in srgb, var(--progress-color, var(--color-primary)) 50%, transparent);
        }
    }

    .progress-bar-label {
        font-size: var(--text-xs);
        font-variant-numeric: tabular-nums;
        color: var(--progress-color-on, var(--color-on-primary));
        white-space: nowrap;
        padding-inline: 0.625rem;
        font-weight: 600;
    }

    .progress--tooltip {
        overflow: visible;
    }

    .progress-tooltip {
        background: var(--progress-color, var(--color-primary));
        color: var(--progress-color-on, var(--color-on-primary));
        font-size: var(--text-xs);
        font-variant-numeric: tabular-nums;
        border-radius: var(--radius-sm);
        box-shadow: 0 4px 12px var(--progress-color, var(--color-primary));
        padding: 0.1875rem 0.5rem;
        font-weight: 600;
        line-height: 1.4;
        position: relative;
        transform: translateX(50%);

        @supports (color: color-mix(in lab, red, red)) {
            box-shadow: 0 4px 12px
                color-mix(in srgb, var(--progress-color, var(--color-primary)) 30%, transparent);
        }

        white-space: nowrap;
        margin-top: -2.5rem;
    }

    .progress-tooltip:after {
        content: '';
        background: var(--progress-color, var(--color-primary));
        width: 6px;
        height: 6px;
        position: absolute;
        bottom: -4px;
        left: 50%;
        transform: translateX(-50%) rotate(45deg);
    }

    .progress--indeterminate .progress-bar {
        border-radius: var(--radius-pill);
        animation: 1.4s cubic-bezier(0.65, 0, 0.35, 1) infinite progress-indeterminate;
        width: 35% !important;
    }

    .progress-bar + .progress-bar {
        box-shadow: -1px 0 #fff9;
    }

    .progress-steps {
        gap: 0.375rem;
        display: flex;
    }

    .progress-step {
        border-radius: var(--radius-pill);
        background: var(--progress-color, var(--color-primary));
        flex: 1;
        height: 0.5rem;

        @supports (color: color-mix(in lab, red, red)) {
            background: color-mix(
                in oklab,
                var(--progress-color, var(--color-primary)) 10%,
                var(--color-bg-muted)
            );
        }

        transition: background var(--duration-base) var(--ease-out);
    }

    .progress-step.is-complete {
        background: var(--progress-color, var(--color-primary));
    }

    .progress-steps--primary {
        --progress-color: var(--color-primary);
        --progress-color-on: var(--color-on-primary);
    }

    .progress-steps--secondary {
        --progress-color: var(--color-secondary);
        --progress-color-on: var(--color-on-secondary);
    }

    .progress-steps--tertiary {
        --progress-color: var(--color-tertiary);
        --progress-color-on: var(--color-on-tertiary);
    }

    .progress-steps--quaternary {
        --progress-color: var(--color-quaternary);
        --progress-color-on: var(--color-on-quaternary);
    }

    .progress-steps--accent {
        --progress-color: var(--color-accent);
        --progress-color-on: var(--color-on-accent);
    }

    .progress-steps--dark {
        --progress-color: var(--color-dark);
        --progress-color-on: var(--color-on-dark);
    }

    .dark-section .progress,
    .dark-section .progress-step:not(.is-complete) {
        background: oklch(from var(--on-surface, #fff) l c h / 0.14);
    }

    .dark-section .progress-label {
        color: var(--on-surface, #fff);
    }

    .dark-section .progress-value {
        color: oklch(from var(--on-surface, #fff) l c h / 0.7);
    }

    @media (prefers-reduced-motion: reduce) {
        .progress--animated .progress-bar {
            animation: none;
        }

        .progress--indeterminate .progress-bar {
            animation-duration: 3s;
        }
    }

    .pricing-card {
        --pricing-accent: var(--color-primary);
        --pricing-accent-soft: var(--color-primary-50);
        --pricing-accent-ink: var(--color-primary-ink);
        --pricing-accent-on: var(--color-on-primary);
        --pricing-pad: 2rem;
        height: 100%;
        padding: var(--pricing-pad);
        background: var(--color-bg);
        border: 1px solid var(--color-border);
        border-radius: var(--radius-card);
        transition:
            transform var(--duration-base) var(--ease-out),
            box-shadow var(--duration-base) var(--ease-out),
            border-color var(--duration-base) var(--ease-out);
        flex-direction: column;
        display: flex;
        position: relative;
    }

    .pricing-card:hover {
        box-shadow: var(--shadow-md);
        border-color: var(--pricing-accent);
        transform: translateY(-4px);

        @supports (color: color-mix(in lab, red, red)) {
            border-color: color-mix(in srgb, var(--pricing-accent) 35%, var(--color-border));
        }
    }

    .pricing-card--primary {
        --pricing-accent: var(--color-primary);
        --pricing-accent-soft: var(--color-primary-50);
        --pricing-accent-ink: var(--color-primary-ink);
        --pricing-accent-on: var(--color-on-primary);
    }

    .pricing-card--secondary {
        --pricing-accent: var(--color-secondary);
        --pricing-accent-soft: var(--color-secondary-50);
        --pricing-accent-ink: var(--color-secondary-ink);
        --pricing-accent-on: var(--color-on-secondary);
    }

    .pricing-card--tertiary {
        --pricing-accent: var(--color-tertiary);
        --pricing-accent-soft: var(--color-tertiary-50);
        --pricing-accent-ink: var(--color-tertiary-ink);
        --pricing-accent-on: var(--color-on-tertiary);
    }

    .pricing-card--quaternary {
        --pricing-accent: var(--color-quaternary);
        --pricing-accent-soft: var(--color-quaternary-50);
        --pricing-accent-ink: var(--color-quaternary-ink);
        --pricing-accent-on: var(--color-on-quaternary);
    }

    .pricing-card--accent {
        --pricing-accent: var(--color-accent);
        --pricing-accent-soft: var(--color-accent-50);
        --pricing-accent-ink: var(--color-accent-ink);
        --pricing-accent-on: var(--color-on-accent);
    }

    .pricing-card--dark {
        --pricing-accent: var(--color-dark);
        --pricing-accent-soft: var(--color-dark-bg);
        --pricing-accent-ink: var(--color-dark);
        --pricing-accent-on: var(--color-on-dark);
    }

    .pricing-card--featured {
        z-index: 1;
        border-color: var(--pricing-accent);
        background-image: linear-gradient(180deg, var(--pricing-accent-soft) 0%, transparent 11rem);
        box-shadow:
            0 0 0 3px var(--pricing-accent),
            var(--shadow-lg);

        @supports (color: color-mix(in lab, red, red)) {
            box-shadow:
                0 0 0 3px color-mix(in srgb, var(--pricing-accent) 10%, transparent),
                var(--shadow-lg);
        }
    }

    .pricing-card--featured:hover {
        box-shadow:
            0 0 0 3px var(--pricing-accent),
            var(--shadow-xl);
        transform: translateY(-4px);

        @supports (color: color-mix(in lab, red, red)) {
            box-shadow:
                0 0 0 3px color-mix(in srgb, var(--pricing-accent) 14%, transparent),
                var(--shadow-xl);
        }

        border-color: var(--pricing-accent);
    }

    @media (width >= 1024px) {
        .pricing-card--featured {
            transform: scale(1.03);
        }

        .pricing-card--featured:hover {
            transform: scale(1.03) translateY(-4px);
        }
    }

    .container > .pricing-card--featured {
        transform: none;
    }

    .container > .pricing-card--featured:hover {
        transform: translateY(-4px);
    }

    .pricing-card--bordered {
        box-shadow: none;
    }

    .pricing-card--bordered:hover {
        box-shadow: none;
        border-color: var(--pricing-accent);
        transform: none;
    }

    .pricing-card--filled {
        background: var(--pricing-accent);
        border-color: var(--pricing-accent);
        color: var(--pricing-accent-on, #fff);
        background-image: linear-gradient(160deg, #ffffff24 0%, #fff0 50%);
    }

    .pricing-card--filled .pricing-plan,
    .pricing-card--filled .pricing-amount,
    .pricing-card--filled .pricing-currency {
        color: var(--pricing-accent-on, #fff);
    }

    .pricing-card--filled .pricing-desc,
    .pricing-card--filled .pricing-period,
    .pricing-card--filled .pricing-feature {
        color: oklch(from var(--pricing-accent-on, #fff) l c h / 0.82);
    }

    .pricing-card--filled .pricing-feature-icon {
        color: var(--pricing-accent-on, #fff);
        background: oklch(from var(--pricing-accent-on, #fff) l c h / 0.18);
    }

    .pricing-card--filled .pricing-divider {
        background: oklch(from var(--pricing-accent-on, #fff) l c h / 0.22);
    }

    .pricing-card--filled .pricing-feature--muted {
        color: oklch(from var(--pricing-accent-on, #fff) l c h / 0.5);
    }

    .pricing-card--filled .pricing-amount--struck {
        color: oklch(from var(--pricing-accent-on, #fff) l c h / 0.6);
    }

    .pricing-card--filled .btn-glass {
        color: var(--pricing-accent-on, #fff);
        background: #ffffff29;
        border-color: #ffffff47;

        &:hover {
            background: #ffffff42;
        }
    }

    .pricing-card--filled:hover {
        border-color: #0000;
    }

    .pricing-card--gradient {
        padding-top: 0;
        overflow: hidden;
    }

    .pricing-card--gradient .pricing-head {
        margin: 0 calc(-1 * var(--pricing-pad)) 1.5rem;
        padding: var(--pricing-pad) var(--pricing-pad) 1.5rem;
        background: linear-gradient(135deg, var(--pricing-accent), var(--pricing-accent));

        @supports (color: color-mix(in lab, red, red)) {
            background: linear-gradient(
                135deg,
                var(--pricing-accent),
                color-mix(in srgb, var(--pricing-accent) 60%, #000)
            );
        }

        color: var(--pricing-accent-on, #fff);
    }

    @supports (color: oklch(from red calc(l + 0.1) c h)) {
        .pricing-card--gradient .pricing-head {
            background: linear-gradient(135deg, var(--pricing-accent), var(--pricing-accent));

            @supports (color: color-mix(in lab, red, red)) {
                background: linear-gradient(
                    135deg,
                    var(--pricing-accent),
                    color-mix(
                        in srgb,
                        var(--pricing-accent) 60%,
                        oklch(
                            from var(--pricing-accent-on, #fff) clamp(0, (0.6 - l) * 1000000000, 1)
                                0 0
                        )
                    )
                );
            }
        }
    }

    .pricing-card--gradient .pricing-head .pricing-plan,
    .pricing-card--gradient .pricing-head .pricing-amount,
    .pricing-card--gradient .pricing-head .pricing-currency {
        color: var(--pricing-accent-on, #fff);
    }

    .pricing-card--gradient .pricing-head .pricing-desc,
    .pricing-card--gradient .pricing-head .pricing-period {
        color: oklch(from var(--pricing-accent-on, #fff) l c h / 0.85);
    }

    .pricing-plan {
        font-size: var(--text-xl);
        color: var(--color-text);
        letter-spacing: -0.025em;
        font-weight: 700;
    }

    .pricing-desc {
        font-size: var(--text-base);
        color: var(--color-text-soft);
        line-height: var(--leading-relaxed);
        text-wrap: pretty;
        margin-top: 0.375rem;
    }

    .pricing-price {
        align-items: baseline;
        gap: 0.25rem;
        margin-top: 1.5rem;
        display: flex;
    }

    .pricing-currency {
        font-size: var(--text-xl);
        color: var(--color-text);
        opacity: 0.7;
        align-self: flex-start;
        margin-top: 0.45rem;
        font-weight: 600;
    }

    .pricing-amount {
        font-size: var(--text-5xl);
        letter-spacing: -0.045em;
        color: var(--color-text);
        font-variant-numeric: tabular-nums;
        font-weight: 700;
        line-height: 1;
    }

    .pricing-amount--struck {
        font-size: var(--text-2xl);
        color: var(--color-text-muted);
        font-weight: 600;
        text-decoration: line-through;
    }

    .pricing-period {
        font-size: var(--text-sm);
        color: var(--color-text-soft);
        font-weight: 500;
    }

    .pricing-divider {
        background: var(--color-border);
        border: 0;
        height: 1px;
        margin-block: 1.5rem;
    }

    .pricing-features {
        flex-direction: column;
        gap: 0.75rem;
        margin: 0;
