        gap: 0.875rem;
        padding: 0.5rem 0.875rem;
        display: inline-flex;
    }

    .pricing-billing-label {
        cursor: pointer;
        font: inherit;
        font-size: var(--text-sm);
        color: var(--color-text-muted);
