        height: 1.625rem;
        font-size: 0.9rem;
        display: inline-flex;
    }

    .pricing-table-check {
        background: var(--color-success-bg);
        color: var(--color-success);
    }

    .pricing-table-dash {
        background: var(--color-bg-soft);
        color: var(--color-text-muted);
    }

    .pricing-table tfoot td {
        padding-top: 1.5rem;
