    .pricing-table-featured .pricing-table-check {
        background: var(--color-surface);
    }

    .pricing-table tbody tr:hover th,
    .pricing-table tbody tr:hover td:not(.pricing-table-featured) {
        background: var(--color-bg-soft);
    }

    .pricing-table--raised {
        --raised-bg: var(--color-dark-surface);
        --raised-on: white;
        --raised-line: oklch(from var(--raised-on) l c h / 0.12);
