        --raised-ring: transparent;
        --raised-lift: 1rem;
        --raised-radius: var(--radius-3xl);

        & :is(th, td) {
            padding: 1.125rem 1.25rem;
            font-size: 1rem;
            line-height: 1.4;
        }

        & thead th {
            padding-top: 1.75rem;
            padding-bottom: 1.5rem;
