            transparent var(--cutout-fade, 62%)
        );

        @supports (color: color-mix(in lab, red, red)) {
            background-image: radial-gradient(
                circle at 50% var(--cutout-y, 40%),
                color-mix(in oklch, var(--color-primary) var(--cutout-glow, 34%), transparent),
                transparent var(--cutout-fade, 62%)
