    }

    .team-card--cutout:is(:hover, :focus-within) .team-card-media {
        background-color: var(--color-primary);

        @supports (color: color-mix(in lab, red, red)) {
            background-color: color-mix(
                in oklch,
                var(--color-primary) var(--cutout-wash, 14%),
