    }

    .team-card--overlay .team-bio,
    .team-card--overlay .team-quote {
        color: #ffffffbf;
    }

    :is(.dark-section, .section-dark) .team-row {
        border-color: oklch(from var(--on-surface, #fff) l c h / 0.12);
