    .frame-ticks {
        --frame-tick-size: 0.6875rem;
        --frame-tick-weight: 1px;
        --frame-tick-color: var(--color-text);

        @supports (color: color-mix(in lab, red, red)) {
            --frame-tick-color: color-mix(in srgb, var(--color-text) 42%, transparent);
        }

        --frame-tick-offset: 0px;
        --frame-line: var(--color-text);

        @supports (color: color-mix(in lab, red, red)) {
            --frame-line: color-mix(in srgb, var(--color-text) 10%, transparent);
        }

        --frame-line-width: 1px;
        border: var(--frame-line-width) solid var(--frame-line);
        background: var(--frame-bg, transparent);
        border-radius: 0;
        position: relative;

        &:before {
            --_tl: var(--frame-tick-color);
            --_tr: var(--frame-tick-color);
            --_bl: var(--frame-tick-color);
            --_br: var(--frame-tick-color);
            --_mid: calc((var(--frame-tick-size) - var(--frame-tick-weight)) / 2);
            --_h: var(--frame-tick-size) var(--frame-tick-weight);
            --_v: var(--frame-tick-weight) var(--frame-tick-size);
            content: '';
            inset: calc(
                (var(--frame-tick-size) + var(--frame-line-width)) / -2 - var(--frame-tick-offset)
            );
            z-index: 1;
            pointer-events: none;
            background:
                linear-gradient(var(--_tl), var(--_tl)) left 0 top var(--_mid) / var(--_h),
                linear-gradient(var(--_tl), var(--_tl)) left var(--_mid) top 0 / var(--_v),
                linear-gradient(var(--_tr), var(--_tr)) right 0 top var(--_mid) / var(--_h),
                linear-gradient(var(--_tr), var(--_tr)) right var(--_mid) top 0 / var(--_v),
                linear-gradient(var(--_bl), var(--_bl)) left 0 bottom var(--_mid) / var(--_h),
                linear-gradient(var(--_bl), var(--_bl)) left var(--_mid) bottom 0 / var(--_v),
                linear-gradient(var(--_br), var(--_br)) right 0 bottom var(--_mid) / var(--_h),
                linear-gradient(var(--_br), var(--_br)) right var(--_mid) bottom 0 / var(--_v);
            background-repeat: no-repeat;
            position: absolute;
        }

        & > :is(img, video, picture, svg):only-child {
            width: 100%;
            display: block;
        }
    }

    .frame-ticks--top:before {
        --_bl: transparent;
        --_br: transparent;
    }

    .frame-ticks--bottom:before {
        --_tl: transparent;
        --_tr: transparent;
    }

    .frame-ticks--diagonal:before {
        --_tr: transparent;
