    .progressive-blur {
        --pb-h: 22vh;
        --pb-blur: 24px;
        --pb-offset: 0px;
        --pb-tint: var(--color-bg);
        height: var(--pb-h);
        pointer-events: none;
        z-index: calc(var(--z-sticky) - 1);
        position: fixed;
        left: 0;
        right: 0;
    }

    .progressive-blur--bottom {
        --pb-dir: to bottom;
        bottom: var(--pb-offset);
    }

    .progressive-blur--top {
        --pb-dir: to top;
        top: var(--pb-offset);
    }

    .progressive-blur-layer {
        position: absolute;
        inset: 0;
    }

    .progressive-blur-layer:first-child {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 128));
        backdrop-filter: blur(calc(var(--pb-blur) / 128));
        mask-image: linear-gradient(var(--pb-dir), transparent 0%, #000 12.5%);
    }

    .progressive-blur-layer:nth-child(2) {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 64));
        backdrop-filter: blur(calc(var(--pb-blur) / 64));
        mask-image: linear-gradient(var(--pb-dir), transparent 12.5%, #000 25%);
    }

    .progressive-blur-layer:nth-child(3) {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 32));
        backdrop-filter: blur(calc(var(--pb-blur) / 32));
        mask-image: linear-gradient(var(--pb-dir), transparent 25%, #000 37.5%);
    }

    .progressive-blur-layer:nth-child(4) {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 16));
        backdrop-filter: blur(calc(var(--pb-blur) / 16));
        mask-image: linear-gradient(var(--pb-dir), transparent 37.5%, #000 50%);
    }

    .progressive-blur-layer:nth-child(5) {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 8));
        backdrop-filter: blur(calc(var(--pb-blur) / 8));
        mask-image: linear-gradient(var(--pb-dir), transparent 50%, #000 62.5%);
    }

    .progressive-blur-layer:nth-child(6) {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 4));
        backdrop-filter: blur(calc(var(--pb-blur) / 4));
        mask-image: linear-gradient(var(--pb-dir), transparent 62.5%, #000 75%);
    }

    .progressive-blur-layer:nth-child(7) {
        -webkit-backdrop-filter: blur(calc(var(--pb-blur) / 2));
        backdrop-filter: blur(calc(var(--pb-blur) / 2));
        mask-image: linear-gradient(var(--pb-dir), transparent 75%, #000 87.5%);
    }

    .progressive-blur-layer:nth-child(8) {
        -webkit-backdrop-filter: blur(var(--pb-blur));
        backdrop-filter: blur(var(--pb-blur));
        mask-image: linear-gradient(var(--pb-dir), transparent 87.5%, #000 100%);
    }

    .progressive-blur--fade:after {
        content: '';
        background: linear-gradient(var(--pb-dir), transparent 0%, var(--pb-tint) 92%);
        position: absolute;
        inset: 0;
    }

    body.glightbox-open .progressive-blur,
    body:has(dialog[open]) .progressive-blur {
        opacity: 0;
    }

    @supports not ((-webkit-backdrop-filter: blur(1px)) or (backdrop-filter: blur(1px))) {
