[x-cloak] {
    display: none !important;
}

.btn-chip-trailing {
    gap: 1rem;
    padding: 0.375rem 0.375rem 0.375rem 1.625rem;
}

.btn-chip-leading {
    gap: 1rem;
    padding: 0.375rem 1.625rem 0.375rem 0.375rem;
}

.btn-xs.btn-chip-trailing {
    gap: 0.5rem;
    padding: 0.1875rem 0.1875rem 0.1875rem 0.75rem;
}

.btn-xs.btn-chip-leading {
    gap: 0.5rem;
    padding: 0.1875rem 0.75rem 0.1875rem 0.1875rem;
}

.btn-sm.btn-chip-trailing {
    gap: 0.625rem;
    padding: 0.25rem 0.25rem 0.25rem 1rem;
}

.btn-sm.btn-chip-leading {
    gap: 0.625rem;
    padding: 0.25rem 1rem 0.25rem 0.25rem;
}

.btn-lg.btn-chip-trailing {
    gap: 1.125rem;
    padding: 0.375rem 0.375rem 0.375rem 2rem;
}

.btn-lg.btn-chip-leading {
    gap: 1.125rem;
    padding: 0.375rem 2rem 0.375rem 0.375rem;
}

.btn-xl.btn-chip-trailing {
    gap: 1.25rem;
    padding: 0.4375rem 0.4375rem 0.4375rem 2.5rem;
}

.btn-xl.btn-chip-leading {
    gap: 1.25rem;
    padding: 0.4375rem 2.5rem 0.4375rem 0.4375rem;
}

@keyframes seal-spin {
    to {
        transform: rotate(360deg);
    }
}

@keyframes badge-pulse-ring {
    0% {
        opacity: 0.7;
        inset: -1px;
    }

    100% {
        opacity: 0;
        inset: -8px;
    }
}

@keyframes badge-dot-pulse {
    0% {
        opacity: 0.8;
        transform: scale(1);
    }

    100% {
        opacity: 0;
        transform: scale(2.2);
    }
}

@keyframes status-pulse {
    0% {
        opacity: 0.55;
        scale: 1;
    }

    70%,
    100% {
        opacity: 0;
        scale: 3;
    }
}

@keyframes mini-ui-ping {
    to {
        opacity: 0;
        scale: 2.6;
    }
}

@keyframes mini-ui-pulse {
    50% {
        scale: 1.3;
    }
}

@keyframes mini-ui-shimmer {
    to {
        background-position: -20% 0;
    }
}

@keyframes mini-ui-march {
    to {
        stroke-dashoffset: -0.1px;
    }
}

@keyframes cta-tag-pulse {
    0% {
        box-shadow: 0 0 0 0 color-mix(in srgb, currentColor 55%, transparent);
    }

    70% {
        box-shadow: 0 0 0 0.45rem color-mix(in srgb, currentColor 0%, transparent);
    }

    100% {
        box-shadow: 0 0 #0000;
    }
}

pre.bg-dark .text-soft {
    color: var(--color-primary-200);
}

pre.bg-dark .color-primary {
    color: var(--color-primary-300);
}

@supports (color: oklch(from red calc(l + 0.1) c h)) {
    pre.bg-dark {
        --color-primary-300: oklch(
            from var(--color-primary-base) max(calc(l + (max(l, 0.97) - l) * 0.536), 0.77)
                calc(c * 0.62) h
        );
    }
}

@property --nx-count {
    syntax: '<integer>';
    inherits: false;
    initial-value: 0;
}

:root {
    --navbar-h: 88px;
    --topbar-h: 44px;
}

:root:has(.header-topbar:not(.scrolled)) {
    --header-h: calc(var(--navbar-h) + var(--topbar-h));
}

:root:has(.header-utility) {
    --navbar-h: 76px;
    --topbar-h: 48px;
    --header-h: 76px;
}

:root:has(.header-contact.scrolled) {
    --header-h: 72px;
    --navbar-h: 72px;
}

:root {
    --float-inset: 1rem;
}

:root:has(.header-floating) {
    --navbar-h: 76px;
    --header-h: calc(var(--navbar-h) + var(--float-inset) * 2);
}

@media (width <= 1023px) {
    :root:has(.header-floating) {
        --float-inset: 0.625rem;
    }
}

:root {
    --capsule-inset: 1rem;
}

:root:has(.header-capsule) {
    --navbar-h: 68px;
    --header-h: calc(var(--navbar-h) + var(--capsule-inset) * 2);
}

:root:has(.header-glass) {
    --navbar-h: 68px;
    --capsule-inset: 0.75rem;
    --header-h: calc(var(--navbar-h) + var(--capsule-inset) * 2);
}

:root:has(.header-capsule:is(.header-topbar, .header-ticker):not(.scrolled)),
:root:has(.header-glass:is(.header-topbar, .header-ticker):not(.scrolled)) {
    --header-h: calc(var(--navbar-h) + var(--capsule-inset) * 2 + var(--topbar-h));
}

@media (width <= 1023px) {
    :root:has(.header-capsule) {
        --capsule-inset: 0.625rem;
    }

    :root:has(.header-glass) {
        --capsule-inset: 0.5rem;
    }
}

:root:has(.header-pill-menu) {
    --navbar-h: 96px;
    --header-h: 96px;
}

:root:has(.header-pill-menu.scrolled) {
    --navbar-h: 76px;
    --header-h: 76px;
}

:root:has(.header-pill-menu:is(.header-topbar, .header-ticker):not(.scrolled)) {
    --header-h: calc(var(--navbar-h) + var(--topbar-h));
}

:root:has(.header-stacked) {
